def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def generate_s(L, n, k):
    s = []
    for i in range(2**n):
        X = bin(i)[2:].zfill(n)
        if hamming_distance(L, X) == k:
            s.append(X)
    return tuple(s)

# Test case: n=3, k=1. L=000, L'=100. d(L, L')=1=k.
n = 3
k = 1
L1 = "000"
L2 = "100"

S1 = generate_s(L1, n, k)
S2 = generate_s(L2, n, k)

print(f"S({L1}) = {S1}")
print(f"S({L2}) = {S2}")
print(f"S1 == S2: {S1 == S2}")
